DO $$ DECLARE f record; definition text; BEGIN FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('ac_operate','ac_verify','ac_recompute') LOOP definition:=pg_get_functiondef(f.oid); definition:=regexp_replace(definition,'BEGIN','BEGIN PERFORM pg_advisory_xact_lock(741025);'); EXECUTE definition; END LOOP; END $$;
COMMENT ON FUNCTION public.ac_recompute(date) IS 'Billing mutations serialize on advisory lock 741025 before customer/invoice locks to avoid cross-customer deadlocks. Partial invoices retain null settled_date; overdue evaluation may supersede PARTIALLY_PAID.';